<?php

/**
 * Tests for the `post_tax_query` argument of WP_Comment_Query.
 * Generated by Claude Code, Model Opus 5.5
 *
 * @group comment
 * @ticket 20597
 *
 * @covers WP_Comment_Query::get_comment_ids
 */
class Tests_Comment_Query_PostTaxQuery extends WP_UnitTestCase {

	protected static $cat_a;
	protected static $cat_b;
	protected static $tag_x;

	protected static $post_a;
	protected static $post_b;
	protected static $post_ab;
	protected static $post_ax;
	protected static $post_none;

	protected static $comment_a;
	protected static $comment_b;
	protected static $comment_ab;
	protected static $comment_ax;
	protected static $comment_none;

	public static function wpSetUpBeforeClass( WP_UnitTest_Factory $factory ) {
		self::$cat_a = $factory->category->create( array( 'slug' => 'cat-a' ) );
		self::$cat_b = $factory->category->create( array( 'slug' => 'cat-b' ) );
		self::$tag_x = $factory->tag->create( array( 'slug' => 'tag-x' ) );

		self::$post_a    = $factory->post->create();
		self::$post_b    = $factory->post->create();
		self::$post_ab   = $factory->post->create();
		self::$post_ax   = $factory->post->create();
		self::$post_none = $factory->post->create(); // Only the default category.

		wp_set_object_terms( self::$post_a, array( self::$cat_a ), 'category' );
		wp_set_object_terms( self::$post_b, array( self::$cat_b ), 'category' );
		wp_set_object_terms( self::$post_ab, array( self::$cat_a, self::$cat_b ), 'category' );
		wp_set_object_terms( self::$post_ax, array( self::$cat_a ), 'category' );
		wp_set_object_terms( self::$post_ax, array( self::$tag_x ), 'post_tag' );

		self::$comment_a    = $factory->comment->create( array( 'comment_post_ID' => self::$post_a ) );
		self::$comment_b    = $factory->comment->create( array( 'comment_post_ID' => self::$post_b ) );
		self::$comment_ab   = $factory->comment->create( array( 'comment_post_ID' => self::$post_ab ) );
		self::$comment_ax   = $factory->comment->create( array( 'comment_post_ID' => self::$post_ax ) );
		self::$comment_none = $factory->comment->create( array( 'comment_post_ID' => self::$post_none ) );
	}

	/**
	 * Runs a comment query returning IDs, merged with the given args.
	 */
	private function query_ids( array $args ) {
		$q = new WP_Comment_Query();
		return $q->query(
			array_merge(
				array( 'fields' => 'ids' ),
				$args
			)
		);
	}

	public function test_single_term() {
		$found = $this->query_ids(
			array(
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_a ),
					),
				),
			)
		);

		$this->assertEqualSets( array( self::$comment_a, self::$comment_ab, self::$comment_ax ), $found );
	}

	public function test_slug_field() {
		$found = $this->query_ids(
			array(
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'slug',
						'terms'    => array( 'cat-b' ),
					),
				),
			)
		);

		$this->assertEqualSets( array( self::$comment_b, self::$comment_ab ), $found );
	}

	/**
	 * A post in several matching terms must not produce duplicate comments.
	 */
	public function test_multiple_terms_in_should_not_return_duplicates() {
		$found = $this->query_ids(
			array(
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_a, self::$cat_b ),
					),
				),
			)
		);

		$this->assertSame( count( $found ), count( array_unique( $found ) ), 'Duplicate comment IDs returned.' );
		$this->assertEqualSets(
			array( self::$comment_a, self::$comment_b, self::$comment_ab, self::$comment_ax ),
			$found
		);
	}

	public function test_operator_and() {
		$found = $this->query_ids(
			array(
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_a, self::$cat_b ),
						'operator' => 'AND',
					),
				),
			)
		);

		$this->assertEqualSets( array( self::$comment_ab ), $found );
	}

	public function test_operator_not_in() {
		$found = $this->query_ids(
			array(
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_a ),
						'operator' => 'NOT IN',
					),
				),
			)
		);

		$this->assertEqualSets( array( self::$comment_b, self::$comment_none ), $found );
	}

	public function test_relation_and_across_taxonomies() {
		$found = $this->query_ids(
			array(
				'post_tax_query' => array(
					'relation' => 'AND',
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_a ),
					),
					array(
						'taxonomy' => 'post_tag',
						'field'    => 'term_id',
						'terms'    => array( self::$tag_x ),
					),
				),
			)
		);

		$this->assertEqualSets( array( self::$comment_ax ), $found );
	}

	public function test_relation_or_across_taxonomies() {
		$found = $this->query_ids(
			array(
				'post_tax_query' => array(
					'relation' => 'OR',
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_b ),
					),
					array(
						'taxonomy' => 'post_tag',
						'field'    => 'term_id',
						'terms'    => array( self::$tag_x ),
					),
				),
			)
		);

		$this->assertEqualSets( array( self::$comment_b, self::$comment_ab, self::$comment_ax ), $found );
	}

	public function test_custom_taxonomy() {
		register_post_type( 'wptests_pt' );
		register_taxonomy( 'wptests_tax', 'wptests_pt' );

		$term    = self::factory()->term->create( array( 'taxonomy' => 'wptests_tax' ) );
		$post    = self::factory()->post->create( array( 'post_type' => 'wptests_pt' ) );
		$comment = self::factory()->comment->create( array( 'comment_post_ID' => $post ) );
		wp_set_object_terms( $post, array( $term ), 'wptests_tax' );

		$found = $this->query_ids(
			array(
				'post_tax_query' => array(
					array(
						'taxonomy' => 'wptests_tax',
						'field'    => 'term_id',
						'terms'    => array( $term ),
					),
				),
			)
		);

		$this->assertEqualSets( array( $comment ), $found );
	}

	public function test_nonexistent_term_returns_no_comments() {
		$found = $this->query_ids(
			array(
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( PHP_INT_MAX ),
					),
				),
			)
		);

		$this->assertSame( array(), $found );
	}

	public function test_empty_post_tax_query_is_ignored() {
		$found = $this->query_ids(
			array(
				'post_tax_query' => array(),
			)
		);

		$this->assertEqualSets(
			array( self::$comment_a, self::$comment_b, self::$comment_ab, self::$comment_ax, self::$comment_none ),
			$found
		);
	}

	/**
	 * Other post fields also join the posts table; it must be joined only once.
	 */
	public function test_combined_with_other_post_fields() {
		$found = $this->query_ids(
			array(
				'post_type'      => 'post',
				'post_status'    => 'publish',
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_b ),
					),
				),
			)
		);

		$this->assertEqualSets( array( self::$comment_b, self::$comment_ab ), $found );
	}

	public function test_combined_with_meta_query() {
		add_comment_meta( self::$comment_a, 'wptests_key', 'foo' );
		add_comment_meta( self::$comment_b, 'wptests_key', 'foo' );

		$found = $this->query_ids(
			array(
				'meta_query'     => array(
					array(
						'key'   => 'wptests_key',
						'value' => 'foo',
					),
				),
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_a ),
					),
				),
			)
		);

		$this->assertEqualSets( array( self::$comment_a ), $found );
	}

	/**
	 * Count must not include duplicates from posts in several matching terms.
	 */
	public function test_count() {
		$q     = new WP_Comment_Query();
		$count = $q->query(
			array(
				'count'          => true,
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_a, self::$cat_b ),
					),
				),
			)
		);

		$this->assertSame( 4, $count );
	}

	/**
	 * Changing a post's terms must invalidate cached comment query results.
	 */
	public function test_cache_is_invalidated_when_post_terms_change() {
		$args = array(
			'post_tax_query' => array(
				array(
					'taxonomy' => 'category',
					'field'    => 'term_id',
					'terms'    => array( self::$cat_b ),
				),
			),
		);

		$before = $this->query_ids( $args );
		$this->assertEqualSets( array( self::$comment_b, self::$comment_ab ), $before );

		wp_set_object_terms( self::$post_a, array( self::$cat_b ), 'category', true );

		$after = $this->query_ids( $args );
		$this->assertEqualSets( array( self::$comment_a, self::$comment_b, self::$comment_ab ), $after );
	}

	public function test_different_tax_queries_should_not_share_cache() {
		$a = $this->query_ids(
			array(
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_a ),
					),
				),
			)
		);

		$b = $this->query_ids(
			array(
				'post_tax_query' => array(
					array(
						'taxonomy' => 'category',
						'field'    => 'term_id',
						'terms'    => array( self::$cat_b ),
					),
				),
			)
		);

		$this->assertEqualSets( array( self::$comment_a, self::$comment_ab, self::$comment_ax ), $a );
		$this->assertEqualSets( array( self::$comment_b, self::$comment_ab ), $b );
	}
}
